input.command:
mkdir -p ../build && cat > ../build/hero.html <<'EOF'
<!doctype html><html><head><meta charset="utf-8"><style>
*{box-sizing:border-box;margin:0;padding:0}
html,body{width:1280px;height:640px;background:#F5F1E8;overflow:hidden}
body{font-family:"Helvetica Neue",Helvetica,Arial,sans-serif;color:#1C1B18;position:relative}
.left{position:absolute;left:72px;top:92px;width:560px}
h1{font-family:"Iowan Old Style",Charter,Georgia,serif;font-weight:700;font-size:78px;line-height:1.02;letter-spacing:-1.5px}
h1 span{background:linear-gradient(transparent 62%,#F2D45C 62%,#F2D45C 92%,transparent 92%);padding:0 4px;margin:0 -4px}
p.sub{margin-top:30px;font-size:25px;line-height:1.42;color:#4B4840;width:520px}
.name{position:absolute;left:72px;bottom:56px;font-size:20px;color:#6A665B;font-family:Menlo,monospace}
.name b{color:#1C1B18}
.chat{position:absolute;left:700px;top:66px;width:508px}
.m{border-radius:18px;padding:16px 20px;font-size:21px;line-height:1.38;margin-bottom:14px;max-width:440px}
.t{background:#fff;border:1.5px solid #DAD3C2;color:#1C1B18;border-bottom-left-radius:5px}
.u{background:#1C1B18;color:#F5F1E8;margin-left:auto;border-bottom-right-radius:5px;max-width:300px}
.who{font-size:14px;letter-spacing:.08em;text-transform:uppercase;color:#8A8576;margin:0 0 6px 4px}
